'use strict';
const W=GravelWeather,R=GravelRoute,P=GravelPlanning,G=Gravel,$=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const APP_VERSION='0.17.6';if(G.version!==APP_VERSION){const message=$('#message');message.textContent='Die Programmdateien stammen aus unterschiedlichen Versionen. Bitte alle Gravel-Outfit-Fenster schließen und die App bei bestehender Internetverbindung erneut öffnen. Deine gespeicherten Daten bleiben erhalten.';throw Error('Versionskonflikt: App '+APP_VERSION+', Bekleidungslogik '+(G.version||'älter'));}
let forecastLoading=false,forecastSequence=0,forecastController=null,routeImportSequence=0;
let historyUI;let db,state,busy=false,queue=Promise.resolve(),editSession=0;
const statusNames={available:'Verfügbar',laundry:'In Wäsche',unavailable:'Nicht verfügbar'};
const say=s=>{$('#message').textContent=s;};
function request(r){return new Promise((resolve,reject)=>{r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
async function openDB(){db=await new Promise((resolve,reject)=>{const r=indexedDB.open('gravel-outfit',6);r.onupgradeneeded=()=>{const d=r.result;if(!d.objectStoreNames.contains('state'))d.createObjectStore('state');if(!d.objectStoreNames.contains('migrationBackups'))d.createObjectStore('migrationBackups');const previous=r.transaction.objectStore('state').get('current');previous.onsuccess=()=>{if(previous.result){r.transaction.objectStore('migrationBackups').put(previous.result,'before-0.9');if([3,4,5,6].includes(previous.result.schemaVersion)){try{r.transaction.objectStore('state').put(G.upgrade(previous.result),'current');}catch(error){say('Datenmigration abgebrochen: '+error.message);r.transaction.abort();}}}};};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);r.onblocked=()=>say('Bitte andere Gravel-Outfit-Tabs schließen, um den Speicher zu öffnen.');});db.onversionchange=()=>{db.close();say('Speicher wurde aktualisiert. Bitte App neu laden.');};}
async function read(){return request(db.transaction('state').objectStore('state').get('current'));}
function write(next){return new Promise((resolve,reject)=>{const tx=db.transaction('state','readwrite');tx.objectStore('state').put(next,'current');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('Speichern abgebrochen'));});}
function preparePersonalState(s){let changed=false;for(const i of s.items){if(i.type==='luprapants'&&i.layer==='Hose'){i.layer='Überhose';changed=true;}}for(const i of s.items){if(!i.model?.trim()){i.model=i.name;changed=true;}if(i.name!==i.model.trim()){i.previousName??=i.name;i.name=i.model.trim();changed=true;}}if(s.rangeModel!=='personal-v1'){s.rangeModel='personal-v1';changed=true;}for(const ride of s.rides){if(!ride.weatherJob&&!ride.actualWeather){const l=ride.weather.forecast?.location;try{ride.weatherJob=GravelHistoryWeather.makeJob(l?.kind==='device'?{kind:'location',...l}:null,ride.startedAt,ride.endedAt);}catch{ride.weatherJob={status:'needs-location',attempts:0};}changed=true;}}return changed;}
function change(fn,options={}){const task=async()=>{busy=true;try{const run=async()=>{const fresh=await read();const next=G.upgrade(fresh||state);await fn(next);preparePersonalState(next);G.validate(next);await write(next);state=next;if(!options.quiet)render();};if(navigator.locks)await navigator.locks.request('gravel-outfit-write',run);else await run();say('Auf diesem Gerät gespeichert.');return true;}catch(e){say('Nicht gespeichert: '+e.message);return false;}finally{busy=false;}};const result=queue.then(task,task);queue=result.then(()=>undefined,()=>undefined);return result;}
const temp=G.displayTemperature;
function temperatureLabels(form,prefix){for(const k of temperatureKeys(form))$('#'+prefix+'-'+k+'-value').textContent=temp(form.elements.namedItem(k).value)+' °C';}
function loadTemperature(form,k,value){const field=form.elements.namedItem(k);field.dataset.original=String(value);field.dataset.touched='false';field.value=form.id==='weather'?Math.max(-10,Math.min(40,temp(value))):temp(value);}
function savedTemperature(form,k){const field=form.elements.namedItem(k);return G.temperatureValue(field.dataset.original,field.value,field.dataset.touched==='true');}
function temperatureKeys(form){return form.id==='weather'?['startTemp','endTemp']:['min','max'];}
function bindTemperatures(form,prefix){for(const k of temperatureKeys(form))form.elements.namedItem(k).addEventListener('input',()=>{const field=form.elements.namedItem(k);field.dataset.touched='true';if(form.id!=='weather'){const lo=form.elements.namedItem('min'),hi=form.elements.namedItem('max');if(savedTemperature(form,'min')>savedTemperature(form,'max')){const other=k==='min'?hi:lo;other.value=field.value;other.dataset.touched='true';}hi.setCustomValidity('');}temperatureLabels(form,prefix);});}
bindTemperatures($('#weather'),'weather');bindTemperatures($('#itemform'),'item');
function fillWeather(){for(const k of Object.keys(G.weather)){if(['startTemp','endTemp'].includes(k))loadTemperature($('#weather'),k,state.weather[k]);else $('#weather').elements[k].value=state.weather[k];}for(const key of Object.keys(G.optionalDefaults()))$('#weather').elements['opt-'+key].value=state.optional[key];temperatureLabels($('#weather'),'weather');for(const k of ['startTemp','endTemp'])if(state.weather[k]< -10||state.weather[k]>40)$('#weather-'+k+'-value').textContent=temp(state.weather[k])+' °C';}
function render(){document.documentElement.dataset.theme=state.appearance||'auto';$('#appearance').value=state.appearance||'auto';fillWeather();renderForecast();renderRecommendation();renderItems();renderRide();renderTourSummary();historyUI?.render();$('#learning-enabled').checked=state.learning.enabled;}
let planningOpen=false,manualWeatherMode=false;
function openManualWeather(){cancelWeather();$('#weather-source').value='manual';persistPlan();manualWeatherMode=true;showPlanning(true);renderPlanPreview();$('#manual-weather').open=true;$('#weather-startTemp').focus();$('#manual-weather').scrollIntoView?.({block:'start',behavior:'smooth'});}
function weatherFailure(message){$('#forecast-status').textContent=message;}
$('#manual-apply').onclick=()=>{manualWeatherMode=true;$('#weather-source').value='manual';};
function showPlanning(open){planningOpen=open;if(!open)manualWeatherMode=false;$('#weather').hidden=!open;$('#outfit-overview').hidden=open;$('#outfit-results').hidden=open;$('#ride-history').hidden=open;$('#tour-bar').hidden=open;if(open)$('#planning-title').focus();else $('#planning-edit')?.focus();}
function renderTourSummary(){const w=state.weather,f=w.forecast,d=P.defaults(state),matches=f&&P.matches(f,d,state.route),stale=f&&(!matches||Date.now()-Date.parse(f.fetchedAt)>3600000||Date.parse(f.endAt)<Date.now());let timing;try{const t=P.windowFor(d,state.route);timing=(d.mode==='now'?'Jetzt':weatherTime(t.startAt))+' · '+durationText(t.ridingMinutes||t.minutes)+(state.route&&d.kind==='outback'?' · '+durationText(d.stayMinutes)+' Aufenthalt':'');}catch(e){timing=d.weatherSource==='route'&&!state.route?(d.mode==='now'?'Jetzt':Number.isFinite(Date.parse(d.startLocal))?weatherTime(d.startLocal):'Startzeit wählen')+' · '+durationText(d.minutes):e.message;}
const source=d.weatherSource==='route'?'Route (GPX)':d.weatherSource==='manual'?'Manuell':'Standort',place=d.weatherSource==='route'?(state.route?.name||'GPX noch nicht gewählt'):d.weatherSource==='manual'?'Eigene Wetterwerte':f?.location?.kind==='device'?P.locationLabel(f).replace('Gerätestandort beim Abruf: ',''):'Ort beim Wetterabruf bestimmen';
$('#tour-summary').innerHTML=`<h3>Deine Tour</h3><p class="tour-time"><strong>${esc(timing)}</strong></p><p class="tour-weather"><strong>${temp(w.startTemp)} → ${temp(w.endTemp)} °C</strong>${f&&matches&&f.minTemperature<Math.min(w.startTemp,w.endTemp)?' · unterwegs bis '+f.minTemperature+' °C':''}<br>${['Trocken','Schauer','Regen'][w.rain]} · ${['wenig Wind','mäßiger Wind','starker Wind'][w.wind]}</p><p class="tour-source"><strong>Wetterquelle: ${source}</strong><br>${esc(place)}</p>${stale?'<p class="warning">Wetter veraltet oder Planung geändert.</p>':!f&&d.weatherSource!=='manual'?'<p class="muted">Noch kein Wetter geladen · bisherige Werte angezeigt.</p>':''}<div class="actions"><button type="button" id="planning-edit">Tour planen</button><button type="button" id="weather-refresh" ${forecastLoading?'disabled':''}>Wetter aktualisieren</button></div><div class="quiet-settings"><label>Intensität<select id="tour-effort"><option value="0">Locker</option><option value="1">Normal</option><option value="2">Sportlich</option></select></label><label>Kälteempfinden<select id="tour-cold"><option value="0">Gering</option><option value="1">Normal</option><option value="2">Hoch</option></select></label></div><p id="summary-status" role="status"></p>${f?'<details><summary>Wetterdetails</summary>'+$('#forecast-location').innerHTML+$('#forecast-source').innerHTML+placeAttribution(f)+'</details>':''}`;
for(const key of ['effort','cold']){const field=$('#tour-'+key);field.value=String(w[key]);field.onchange=e=>{const value=+e.target.value;$('#weather').elements[key].value=value;change(s=>{s.weather[key]=value;});};}
$('#planning-edit').onclick=()=>showPlanning(true);$('#weather-refresh').onclick=async()=>{cancelWeather();$('#weather-refresh').disabled=true;$('#summary-status').textContent='Aktueller Standort wird geladen …';$('#weather-source').value='device';manualWeatherMode=false;await persistPlan();$('#weather-refresh').disabled=true;await automaticWeather({freshLocation:true});$('#summary-status').textContent=$('#forecast-status').textContent;$('#weather-refresh').disabled=false;};}
async function choosePlanningSource(source){cancelWeather();$('#weather-source').value=source;await persistPlan();renderPlanPreview();}
$('#choose-route').onclick=()=>choosePlanningSource('route');$('#choose-manual').onclick=()=>choosePlanningSource('manual');$('#choose-device').onclick=()=>choosePlanningSource('device');
for(const id of ['forecast-day','forecast-time'])$('#'+id).addEventListener('change',()=>{try{$('#forecast-date').value=GravelUIPlanning.combine($('#forecast-day').value,$('#forecast-time').value);persistPlan();}catch(e){$('#forecast-status').textContent=e.message;}});
$('#forecast-mode').addEventListener('change',()=>{if($('#forecast-mode').value==='planned'){try{$('#forecast-date').value=GravelUIPlanning.combine($('#forecast-day').value,$('#forecast-time').value);$('#forecast-day').showPicker?.();}catch{} }persistPlan();});
$('#planning-save').onclick=async()=>{const draft=forecastDraft();try{P.windowFor(draft,state.route);}catch(e){$('#forecast-status').textContent=e.message;return;}if(draft.weatherSource==='manual'){$('#weather').requestSubmit();return;}$('#planning-save').disabled=true;try{await persistPlan();await automaticWeather();const status=$('#forecast-status').textContent;showPlanning(false);$('#summary-status').textContent=status;}finally{$('#planning-save').disabled=false;}};
$('#planning-back').onclick=()=>showPlanning(false);
function durationText(n){const h=Math.floor(n/60),m=n%60;return h?(h===1?'1 Stunde':h+' Stunden')+(m?' '+m+' Minuten':''):n+' Minuten';}
function durationChoices(select,value){select.innerHTML=Array.from({length:12},(_,i)=>{const n=(i+1)*30;return `<option value="${n}">${durationText(n)}</option>`;}).join('');if(!Array.from(select.options).some(x=>+x.value===value))select.add(new Option(value+' Minuten (bisher gespeichert)',String(value)));select.value=String(value);}
function stayChoices(value){const select=$('#stay-minutes');select.innerHTML=Array.from({length:25},(_,i)=>{const n=i*30;return `<option value="${n}">${n?durationText(n):'Kein Aufenthalt'}</option>`;}).join('');if(!Array.from(select.options).some(x=>+x.value===value))select.add(new Option((value%30?value+' Minuten':durationText(value))+' (bisher gespeichert)',String(value)));select.value=String(value);}
function forecastDraft(){return {weatherSource:$('#weather-source').value,mode:$('#forecast-mode').value,startLocal:$('#forecast-date').value,minutes:+$('#ride-minutes').value,kind:$('#route-kind').value,returnMinutes:+$('#return-minutes').value,stayMinutes:+$('#stay-minutes').value};}
function forecastMatches(f,d){return P.matches(f,d,state.route);}
function renderRouteInfo(d){const r=state.route;$('#route-controls').hidden=d.weatherSource!=='route';$('#manual-weather').hidden=d.weatherSource!=='manual';if(d.weatherSource==='manual')$('#manual-weather').open=true;$('#choose-route').setAttribute('aria-pressed',String(d.weatherSource==='route'));$('#choose-manual').setAttribute('aria-pressed',String(d.weatherSource==='manual'));$('#choose-device').hidden=d.weatherSource==='device';$('#weather-source-info').textContent=d.weatherSource==='device'?'Standard: Wetter am Standort.':d.weatherSource==='route'?'Wetter entlang deiner GPX-Strecke.':'Wetter selbst festlegen.';$('#weather-auto').hidden=true;$('#weather-privacy').innerHTML=d.weatherSource==='route'?'Die GPX bleibt lokal. Gerundete Streckenpunkte werden beim Abruf an Open-Meteo übertragen.':'Beim Abruf wird der gerundete Gerätestandort an Open-Meteo übertragen.';$('#route-remove').hidden=!r;$('#route-plan').hidden=!r;$('#return-plan').hidden=!r||d.kind!=='outback';$('#ride-duration-label').textContent=r&&d.kind==='outback'?'Dauer Hinfahrt':'Dauer';$('#route-info').innerHTML=r?`<p><strong>${esc(r.name)}</strong> · ${(r.totalM/1000).toFixed(1)} km</p>`:'<p class="muted">Bitte eine GPX-Datei auswählen.</p>';}
function syncPlanningClock(d){const value=d.mode==='planned'?d.startLocal:W.localInput(GravelUIPlanning.nextQuarter());const day=String(value).slice(0,10),time=String(value).slice(11,16);$('#forecast-day').value=day;$('#forecast-day').min=W.localInput(Date.now()).slice(0,10);$('#forecast-day').max=W.localInput(Date.now()+6*86400000).slice(0,10);$('#forecast-time').innerHTML=GravelUIPlanning.times(time).map(v=>`<option value="${v}">${v}${+v.slice(3)%15?' (bisher gespeichert)':''}</option>`).join('');$('#forecast-time').value=time;}
function renderPlanPreview(){if(!state)return;const d=forecastDraft();$('#forecast-date-label').hidden=d.mode!=='planned';renderRouteInfo(d);if(d.weatherSource==='route'&&!state.route){$('#plan-preview').textContent='';return;}try{const t=P.windowFor(d,state.route);$('#plan-preview').innerHTML=`<p class="muted">${state.route&&d.kind==='outback'?'Rückfahrt ab '+esc(weatherTime(t.returnStartAt))+' · ':''}Ende: ${esc(weatherTime(t.endAt))}</p>`;}catch(e){$('#plan-preview').innerHTML=`<p class="warning">${esc(e.message)}</p>`;}}
async function persistPlan(){if(!state)return;manualWeatherMode=$('#weather-source').value==='manual';const d=forecastDraft();if(!Number.isFinite(d.stayMinutes)||d.stayMinutes<0||d.stayMinutes>1440||d.stayMinutes%5){renderPlanPreview();return;}await change(s=>{s.tripPlan=d;},{quiet:true});renderPlanPreview();renderTourSummary();$('#forecast-status').textContent=state.weather.forecast&&!forecastMatches(state.weather.forecast,d)?'Planung geändert · Wetter beim Speichern aktualisieren.':'Planung vorbereitet.';}
function cancelWeather(){if(!forecastLoading)return;forecastSequence++;forecastController?.abort();forecastLoading=false;$('#weather-auto').disabled=false;$('#weather-auto').removeAttribute('aria-busy');$('#forecast-status').textContent='Abruf abgebrochen, weil die Planung geändert wurde. Bisherige Werte bleiben erhalten.';}
function laterLabel(){const f=state.weather.forecast;return f&&f.minTemperature<Math.min(state.weather.startTemp,state.weather.endTemp)?'Kältester späterer Abschnitt':'Tourende';}
function weatherTime(iso){return new Date(iso).toLocaleString('de-DE',{dateStyle:'short',timeStyle:'short'});}
function weatherOrigin(w){return w.forecast?`<p>Wetterquelle: <a href="https://open-meteo.com/" target="_blank" rel="noopener noreferrer">Open-Meteo</a> · abgerufen ${esc(weatherTime(w.forecast.fetchedAt))} · Prognose für ${esc(weatherTime(w.forecast.startAt))} bis ${esc(weatherTime(w.forecast.endAt))}.${w.forecast.location?' '+esc(P.locationLabel(w.forecast)):''}</p>`:'<p class="muted">Wetter: manuell eingegeben.</p>';}
function placeAttribution(f){return f?.location?.placeName?'<p class="muted">Ortsname: <a href="https://www.bigdatacloud.com/" target="_blank" rel="noopener noreferrer">BigDataCloud</a>.</p>':'';}

function renderForecast(){const w=state.weather,f=w.forecast,d=P.defaults(state);$('#weather-source').value=d.weatherSource;durationChoices($('#ride-minutes'),d.minutes);durationChoices($('#return-minutes'),d.returnMinutes);$('#route-kind').value=d.kind;stayChoices(d.stayMinutes);$('#forecast-mode').value=d.mode;$('#forecast-date').value=d.startLocal;syncPlanningClock(d);$('#forecast-date').min=W.localInput(Date.now());$('#forecast-date').max=W.localInput(Date.now()+6*86400000);$('#forecast-timezone').textContent='Gerätezeit: '+Intl.DateTimeFormat().resolvedOptions().timeZone+' · Datum und Uhrzeit gelten für den Tourstart.';$('#weather-auto').disabled=forecastLoading;renderPlanPreview();$('#forecast-location').innerHTML=f?'<strong>Standort der geladenen Prognose:</strong> '+esc(P.locationLabel(f))+(f.location?` · <a href="https://www.openstreetmap.org/?mlat=${f.location.latitude}&mlon=${f.location.longitude}#map=12/${f.location.latitude}/${f.location.longitude}" target="_blank" rel="noopener noreferrer">Auf OpenStreetMap prüfen</a>`:''):'Noch kein Wetterstandort abgerufen.';
 if(!f){$('#forecast-source').innerHTML='<p class="muted">Noch keine Wetterprognose übernommen. Die Regler können weiterhin manuell verwendet werden.</p>';return;}
 const old=Date.now()-Date.parse(f.fetchedAt)>3600000||Date.parse(f.endAt)<Date.now(),offline=!navigator.onLine;$('#forecast-source').innerHTML=`<div class="forecast-summary">${weatherOrigin(w)}<p><strong>${f.mode==='now'?'Tourstart jetzt':'Geplante Tour'}</strong> · ${esc(weatherTime(f.startAt))} → ${esc(weatherTime(f.endAt))} · ${f.minutes} Minuten Gesamtzeit</p>${f.route?`<p><strong>Strecke:</strong> ${esc(f.route.name)} · ${(f.route.distanceM/1000).toFixed(1)} km · ${f.route.waypointCount} Wetterstützpunkte<br>${f.route.kind==='outback'?'Hinfahrt':'Fahrzeit'}: ${f.route.outboundMinutes} Minuten${f.route.kind==='outback'?` · Aufenthalt: ${durationText(f.route.stayMinutes)} · Rückfahrt: ${f.route.returnMinutes} Minuten<br>Ankunft: ${esc(weatherTime(f.route.arrivalAt))} · Rückfahrt ab ${esc(weatherTime(f.route.returnStartAt))}`:''}</p>`:''}${f.journey?`<p>Tourplanung: ${esc(f.journey.name)} · ${f.journey.outboundMinutes+f.journey.returnMinutes} Minuten Fahrzeit${f.journey.stayMinutes?' · '+durationText(f.journey.stayMinutes)+' Aufenthalt':''}. Wetter bleibt am Gerätestandort; die GPX bestimmt nur die Zeitplanung.</p>`:''}<p>Am Start <strong>${f.start.temperature} °C</strong> · Am Ende <strong>${f.end.temperature} °C</strong><br>Unterwegs ${f.minTemperature} bis ${f.maxTemperature} °C</p><p>Stärkster Wind ${f.maxWind} km/h · Böen bis ${f.maxGust} km/h<br>Niederschlag im Zeitraum ca. ${f.precipitationSum.toLocaleString('de-DE')} mm · höchste Niederschlagswahrscheinlichkeit ${f.maxProbability} %</p><p class="muted">${f.route?'Stichproben entlang der GPX-Strecke zu geschätzten Durchfahrtszeiten bei gleichmäßigem Tempo; kein lückenloses Streckenwetter.':'Modellprognose am angefragten Gerätestandort; keine Wetterstation.'} Die Empfehlung berücksichtigt den Start sowie mitgenommene Kleidung für den kältesten Abschnitt und den stärksten Wind-/Nässeschutzbedarf während der Tour.</p>${old||offline?`<p class="warning">${offline?'Offline: gespeicherte Prognose.':'Diese Prognose ist älter oder ihr Zeitraum liegt bereits zurück.'} Bitte vor der Fahrt erneut abrufen, wenn eine Verbindung besteht.</p>`:''}<details><summary>Temperaturverlauf im Tourzeitraum</summary><ul>${f.timeline.map(p=>`<li>${esc(weatherTime(p.at))}${p.phase?' · '+esc(p.phase)+' · km '+esc(p.km):''}: ${p.temperature} °C${p.windKmH!==undefined?' · Wind '+esc(p.windKmH)+' km/h · '+esc(['Trocken','Schauer möglich','Nass'][p.rain])+' · '+esc(p.probability)+' % Niederschlagswahrscheinlichkeit':''}</li>`).join('')}</ul></details><small>Wetterdaten: <a href="https://open-meteo.com/" target="_blank" rel="noopener noreferrer">Open-Meteo</a> · <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener noreferrer">CC BY 4.0</a>. Temperaturen gerundet; Wind und Niederschlag für die Kleiderwahl zusammengefasst. ${f.usedCurrent?'Starttemperatur aus aktuellen Modellwerten.':'Start- und Endtemperatur aus stündlicher Prognose interpoliert.'}</small></div>`;}
async function automaticWeather({freshLocation=false}={}){if(!state)return;if($('#weather-source').value==='manual'){openManualWeather();return;}if($('#weather-source').value==='device'&&!window.isSecureContext){weatherFailure('Standortabfrage benötigt HTTPS oder localhost. Du kannst das Wetter selbst eingeben.');return;}if(!navigator.onLine){weatherFailure('Offline: Du kannst das Wetter selbst eingeben. Gespeicherte Werte bleiben erhalten.');return;}const savedRouteId=state.route?.id||null,draft=forecastDraft(),route=P.activeRoute(draft,state.route)?structuredClone(state.route):null;try{P.windowFor(draft,route);}catch(e){weatherFailure(e.message);return;}const form=$('#weather'),extras=Object.fromEntries(Object.keys(G.optionalDefaults()).map(k=>[k,form.elements['opt-'+k].value])),effort=+form.elements.effort.value,cold=+form.elements.cold.value,original=JSON.stringify(state.weather),sequence=++forecastSequence;forecastController?.abort();const controller=forecastController=new AbortController();forecastLoading=true;$('#weather-auto').disabled=true;$('#weather-auto').setAttribute('aria-busy','true');$('#forecast-status').textContent=route?'Wetter entlang der Strecke und während des Aufenthalts wird abgefragt …':'Gerätestandort wird bestimmt und Wetter wird geladen …';const timeout=setTimeout(()=>controller.abort(),45000);try{const saved=await change(s=>{s.tripPlan=draft;},{quiet:true});if(!saved||sequence!==forecastSequence)return;const f=route?await R.request({route,plan:draft,signal:controller.signal}):await W.request({...draft,minutes:P.windowFor(draft,state.route).minutes,routeTrip:!!state.route,maximumAge:freshLocation?0:300000,resolvePlace:true,lastLocation:state.weather.forecast?.location,signal:controller.signal});if(!route&&state.route){const t=R.tripFor(draft,Date.parse(f.startAt));f.journey={id:state.route.id,name:state.route.name,distanceM:state.route.totalM*(draft.kind==='outback'?2:1),kind:draft.kind,outboundMinutes:draft.minutes,returnMinutes:draft.kind==='outback'?draft.returnMinutes:0,stayMinutes:draft.kind==='outback'?draft.stayMinutes:0,arrivalAt:t.arrivalAt,returnStartAt:t.returnStartAt,waypointCount:1};}if(sequence!==forecastSequence)return;const ok=await change(s=>{if(JSON.stringify(s.weather)!==original||(s.route?.id||null)!==savedRouteId||!P.matches(f,P.defaults(s),s.route))throw Error('Planung zwischenzeitlich geändert. Bitte erneut abrufen.');s.weather=W.apply({...s.weather,effort,cold},f);s.weather.planning={mode:f.mode,startAt:f.startAt};s.optional=extras;});if(ok){manualWeatherMode=false;$('#forecast-status').textContent='Wetter und Standort übernommen. Empfehlung aktualisiert. Quelle: Open-Meteo.';}}catch(e){if(sequence===forecastSequence)weatherFailure(e.message);}finally{clearTimeout(timeout);if(sequence===forecastSequence){forecastLoading=false;$('#weather-auto').disabled=false;$('#weather-auto').removeAttribute('aria-busy');}}}
$('#weather-auto').onclick=automaticWeather;
for(const id of ['weather-source','forecast-date','ride-minutes','route-kind','return-minutes','stay-minutes'])$('#'+id).addEventListener('change',persistPlan);
$('#weather').addEventListener('input',()=>{cancelWeather();if(state)renderPlanPreview();});
$('#route-file').onchange=async e=>{const file=e.target.files?.[0],importSequence=++routeImportSequence;if(!file)return;cancelWeather();try{if(file.size>5*1024*1024)throw Error('Bitte eine GPX-Datei bis 5 MB wählen.');const text=await file.text();if(importSequence!==routeImportSequence)return;const route=R.parseGPX(text,file.name),draft=forecastDraft();draft.weatherSource='route';if(draft.minutes<30||draft.minutes>360||draft.minutes%30)draft.minutes=90;await change(s=>{s.route=route;s.tripPlan=draft;});$('#forecast-status').textContent='GPX-Datei lokal übernommen. Zum Abrufen der Streckenprognose bitte Streckenwetter laden.';}catch(error){say(error.message);e.target.value='';}};
$('#route-remove').onclick=()=>{routeImportSequence++;cancelWeather();change(s=>{delete s.route;if(s.weather.forecast?.route||s.weather.forecast?.journey)delete s.weather.forecast;const d=P.defaults(s);d.kind='single';if(d.weatherSource==='route')d.weatherSource='device';s.tripPlan=d;});$('#route-file').value='';};
function modelTable(assessment,w){const req=G.requirements(G.learnWeather(w,state));return `<div class="table-scroll"><table><thead><tr><th>Körperzone</th><th>Wärme</th><th>Windschutz</th><th>Regenschutz</th><th>Atmung</th></tr></thead><tbody>${['torso','legs'].map(z=>{const a=assessment[z],target=req[z];return `<tr><th>${z==='torso'?'Oberkörper':'Beine'}</th><td>${a.warmth.toFixed(1)} / Ziel ${target.warmth.toFixed(1)}</td><td>${a.wind.toFixed(1)} / Ziel ${target.wind.toFixed(1)}</td><td>${a.rain} / Ziel ${target.rain}</td><td>${a.breathability.toFixed(1)} / Ziel ${req.breathability.toFixed(1)}</td></tr>`;}).join('')}</tbody></table></div>`;}
function assessmentHTML(start,end){return `<details class="assessment"><summary>Schutz der gesamten Kombination</summary><p class="muted">Relative Modellwerte, keine Materialmessung. Wärme, Windschutz, Nässeschutz und Atmung werden getrennt bewertet. Regen: 0 = gering, 1 = wasserabweisend/teilweise, 2 = wasserdicht. Tourende berücksichtigt die tatsächlich mitgenommenen zusätzlichen Teile und die genannten Ablegehinweise.</p><h4>Tourstart · ${temp(state.weather.startTemp)} °C</h4>${modelTable(start,G.pointWeather(state.weather,'start'))}<h4>${laterLabel()} · ${temp(G.pointWeather(state.weather,'end').temperature)} °C</h4>${modelTable(end,G.pointWeather(state.weather,'end'))}</details>`;}
function outfitLines(rows){return rows.length?rows.map(x=>`<div class="line"><div><button class="garment-link" data-properties-id="${esc(x.item.id)}" data-variant="${esc(x.item.selectedVariant||'')}">${esc(x.item.name)}${x.item.selectedVariant?' · '+esc(G.lengthLabel(x.item.type,x.item.selectedVariant)):''}</button>${x.item.length!=='unspecified'&&!x.item.selectedVariant?'<small>'+esc(G.lengthLabel(x.item.type,x.item.length))+'</small>':''}</div><span class="action-chip ${x.group==='pack'?'action-pack':'action-wear'}">${x.incomplete?'Grundlage':x.group==='pack'?'Mitführen':'Anziehen'}</span></div>`).join(''):'<p class="muted">Keine zusätzliche Kleidung vorgesehen.</p>';}
function packLines(r){const entries=[...r.rows.filter(x=>x.group==='pack').map(row=>({item:row.item,html:outfitLines([row])})),...(r.packComponents||[]).map(c=>({item:state.items.find(i=>i.id===c.parentId),html:`<div class="line" data-pack-component="${esc(c.kind)}"><div><button class="garment-link" data-properties-id="${esc(c.parentId)}" data-variant="long">${esc(c.name)}</button><p>${c.kind==='zipoff-sleeves'?'Oberteil · Abnehmbare Ärmel desselben Oberteils':esc(G.layerOf(state.items.find(i=>i.id===c.parentId)||'rr'))+' · Abnehmbare Hosenbeine derselben Hose'} · Für die lange Variante am Tourende</p></div><span class="action-chip action-pack">Mitführen</span></div>`}))];entries.sort((a,b)=>G.layerNames.indexOf(G.layerOf(a.item||'rr'))-G.layerNames.indexOf(G.layerOf(b.item||'rr')));return entries.map(x=>x.html).join('')||'<p>Keine zusätzlichen verfügbaren Teile.</p>';}

function replacementHTML(r){const stages=[['Tourstart',r.replacements?.start],['Tourende',r.replacements?.end]].filter(([,x])=>x);return stages.length?`<div class="replacement-summary"><h3>Ersatzkombination für die Beine</h3>${stages.map(([stage,x])=>`<div class="panel"><h4>${stage} · Ersatz für eine ${esc(x.target)}</h4><p><strong>${x.items.map(i=>esc(i.name)).join(' + ')}</strong></p><p>${esc(x.explanation)}</p><p><strong>Windschutz:</strong> ${x.windSufficient?'Modellanforderung erfüllt':'noch eingeschränkt'} · <strong>Wärme:</strong> ${x.warmthSufficient?'Modellanforderung erfüllt':'nicht ausreichend'}</p><p class="${x.status==='red'?'warning':'muted'}"><strong>${x.status==='red'?'Unzureichender Ersatz':'Ersatzlösung'}:</strong> ${esc(x.limitation)}</p></div>`).join('')}</div>`:'';}
function sourceAssessmentHTML(r){return `<details class="excel-assessment"><summary>Excel-Bewertung der Ersatzlösungen</summary><p>Diese Bewertungen beschreiben die fachliche Eignung. Sie sind unabhängig von den Aktionsfarben für Anziehen und Mitnehmen.</p>${[['Tourstart',r.sourceStatus.start],['Tourende',r.sourceStatus.end]].map(([title,rows])=>`<h4>${title}</h4>${rows.map(c=>`<p class="excel-status excel-${c.status}"><strong>${esc(c.category)} · ${{green:'Vorhanden / passend',yellow:'Ersatzlösung',red:'Unzureichend',missing:'Fehlt'}[c.status]}</strong><br>${esc(c.reason)}<small>${c.refs.map(esc).join(' · ')}</small></p>`).join('')}`).join('')}</details>`;}
let propertyItemId=null;
function openProperties(id,variant){const i=state.items.find(x=>x.id===id);if(!i)return;propertyItemId=id;const c=G.catalogOf(i),modelItem=variant?{...i,length:variant}:i;const known=x=>x===null||x===undefined||x===''?'Nicht hinterlegt':esc(x);$('#properties-title').textContent=i.name;$('#properties-content').innerHTML=`<dl><dt>Hersteller</dt><dd>${known(i.manufacturer||c?.manufacturer)}</dd><dt>Modell</dt><dd>${known(i.model||c?.model)}</dd><dt>Bekleidungskategorie</dt><dd>${esc(G.layerOf(i))}</dd><dt>Art</dt><dd>${esc(G.types[i.type])}</dd><dt>Tragevariante</dt><dd>${variant?esc(G.lengthLabel(i.type,variant)):i.variants.length>1?i.variants.map(v=>esc(G.lengthLabel(i.type,v))).join(' / '):esc(G.lengthLabel(i.type,i.length))}</dd><dt>Dein Temperaturbereich</dt><dd>${temp(i.min)} bis ${temp(i.max)} °C</dd><dt>Gelernter Bereich für aktuelle Planung</dt><dd>${(()=>{const l=GravelPersonal.effectiveRange(i,state,G.pointWeather(state.weather));return temp(l.min)+' bis '+temp(l.max)+' °C · '+l.count+' passende Erfahrungen';})()}</dd><dt>Wärmeleistung (hinterlegt)</dt><dd>${known(i.warmthRating)}</dd><dt>Windschutz (hinterlegt)</dt><dd>${i.windRating!==null?known(i.windRating):i.source?.startsWith('Excel')?'Keine technische Angabe hinterlegt; siehe Modellannahmen':i.wind?'Als winddicht erfasst':'Keine bestätigte Windschutzangabe'}</dd><dt>Regenschutz (hinterlegt)</dt><dd>${i.rainRating!==null?known(i.rainRating):i.source?.startsWith('Excel')?'Keine technische Angabe hinterlegt; siehe Modellannahmen':i.rain?'Als wasserdicht erfasst':i.waterRepellent?'Als wasserabweisend erfasst':'Keine bestätigte Regenschutzangabe'}</dd><dt>Atmungsaktivität (hinterlegt)</dt><dd>${known(i.breathabilityRating)}</dd><dt>Verfügbarkeit</dt><dd>${i.archived?'Archiviert':statusNames[i.status]}</dd></dl><details><summary>Davon getrennte Modellannahmen</summary><p>Relative Modellwerte, keine bestätigten Herstellerkennwerte: Wärme ${G.traits(modelItem).warmth.toFixed(1)}, Wind ${G.traits(modelItem).wind.toFixed(1)}, Regen ${G.traits(modelItem).rain}, Atmung ${G.traits(modelItem).breathability.toFixed(1)}.</p></details>${i.notes?`<p>${esc(i.notes)}</p>`:''}`;$('#properties').showModal();}
$('#properties-close').onclick=()=>$('#properties').close();$('#properties-edit').onclick=()=>{$('#properties').close();edit(propertyItemId);};
document.addEventListener('click',e=>{const b=e.target.closest('[data-properties-id]');if(b)openProperties(b.dataset.propertiesId,b.dataset.variant);});
function baselayerDiagnostic(r){const selected=r.rows.find(x=>x.group==='start'&&['base','winterbase'].includes(x.item.type))?.item;return `<details><summary>Baselayer-Auswahl prüfen</summary><p>Berechnungsstand ${esc(G.version)} · niedrigste Tourtemperatur ${temp(r.baselayerPlan.minimum)} °C · Anforderung ${r.baselayerPlan.personal?'dein persönlicher Temperaturbereich':esc({short:'mindestens Kurzarm',thermalLong:'Thermo-Langarm',light:'leichte Basis',sleeveless:'ärmellose Basis'}[r.baselayerPlan.target])}.</p><p>Automatisch gewählt: <strong>${selected?esc(selected.name)+' · '+esc(G.lengthLabel(selected.type,selected.length)):'Keine verfügbare Basis'}</strong>${r.baselayerPlan.fallback?' · eingeschränkter Ersatz':''}.</p><ul>${state.items.filter(i=>['base','winterbase'].includes(i.type)).map(i=>`<li>${esc(i.name)} · ${esc(G.lengthLabel(i.type,i.length))} · ${i.archived?'Archiviert':esc(statusNames[i.status])}${i.lengthReviewRequired?' · Längenangabe prüfen':''}${i.id===selected?.id?' · gewählt':''}</li>`).join('')}</ul><p>Die gespeicherte Ärmellänge zählt; der Name allein ersetzt sie nicht. Bei Eigene Auswahl bleibt deine manuelle Auswahl unverändert.</p></details>`;}
function renderRecommendation(){const r=G.recommend(state),manual=G.manualAssessment(state),isManual=state.plan.mode==='manual',selected=state.plan.selectedIds,choices=G.sortItems(state.items.filter(i=>G.usable(i)||selected.includes(i.id))),actual=isManual?manual.items.map(item=>({item,group:'start',reason:G.types[item.type]})):r.rows,assessment=isManual?manual.assessment:r.assessment,endAssessment=isManual?manual.endAssessment:r.endAssessment,warnings=isManual?manual.warnings:r.warnings,unique=[...new Set(warnings.map(w=>w.replace(/^(Tourstart|Tourende|Später): /,'')))];
const open=[];for(const zone of ['torso','legs']){const a=endAssessment[zone],name=zone==='torso'?'Oberkörper':'Beine';if(a.gaps.foundation||a.gaps.outer)open.push(name+': geeignete Grund- oder Außenschicht fehlt');if(a.gaps.rain>0)open.push(name+': Nässeschutz eingeschränkt');if(a.gaps.wind>.15)open.push(name+': Windschutz eingeschränkt');if(a.gaps.warmth>.8)open.push(name+': zusätzliche Wärme nötig');}
const replacement=Object.values(r.replacements||{}).filter(Boolean),replaced=replacement.filter(x=>x.status!=='red'),manualHTML=`<div id="manual-outfit" ${isManual?'':'hidden'}><div class="actions"><h3>Eigene Kombination</h3><button type="button" data-mode="recommended">Empfehlung verwenden</button></div><fieldset class="manual-list"><legend>Verfügbarer Kleiderschrank</legend>${choices.map(i=>`<label class="manual-choice"><input type="checkbox" data-select-id="${esc(i.id)}" ${selected.includes(i.id)?'checked':''}><span>${esc(i.name)}<small>${G.usable(i)?'Verfügbar':'Nicht verfügbar – zum Entfernen abwählen'}</small></span></label>${i.variants.length>1?`<label>Tragevariante<select data-manual-variant="${esc(i.id)}">${i.variants.map(v=>`<option value="${v}" ${(state.plan.variantSelections?.[i.id]||i.length)===v?'selected':''}>${G.lengthLabel(i.type,v)}</option>`).join('')}</select></label>`:''}`).join('')}<button type="button" data-clear-selection>Auswahl leeren</button></fieldset></div>`;
$('#recommendation').innerHTML=`<h2>Dein Outfit${isManual?' · eigene Auswahl':''}</h2><h3>Anziehen</h3>${outfitLines(actual.filter(x=>x.group==='start'))}<h3>Mitführen</h3>${isManual?'<p class="muted">In der eigenen Auswahl als Startkleidung erfasst.</p>':packLines(r)}<section class="outfit-assessment"><h3>Einordnung</h3>${!r.wearable&&!isManual?'<p class="warning">Noch kein vollständiges, tragbares Outfit.</p>':!open.length?(unique.length?'<p>Nach aktuellem Modell tragbar. Bitte die Hinweise beachten.</p>':'<p>Die gewählte Kombination deckt den berechneten Schutzbedarf ab.</p>'):'<p>Es bleiben Einschränkungen beim Schutz.</p>'}${replaced.length&&!isManual?'<p><strong>Durch Kombination ergänzt:</strong> '+[...new Set(replaced.map(x=>x.items.map(i=>esc(i.name)).join(' + ')))].join('; ')+'.</p>':''}${!isManual&&r.continuous?'<p class="muted">Möglichst ohne Kleidungswechsel – am Start etwas wärmer.</p>':''}${open.length?'<p><strong>Offen im Kleiderschrank:</strong></p><ul>'+[...new Set(open)].map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul><p class="muted">Geeignete zusätzliche Kleidung könnte helfen. Zuerst gespeicherte Eigenschaften und verfügbare Kombinationen prüfen.</p>':''}${unique.length?'<details class="outfit-warnings"><summary>Hinweise zur Kleidung ('+unique.length+')</summary>'+unique.map(w=>'<p class="warning">'+esc(w)+'</p>').join('')+'</details>':''}${!isManual&&r.variantChanges.length?'<p>'+r.variantChanges.map(v=>esc(v.name)+': '+G.lengthLabel(state.items.find(i=>i.id===v.id)?.type||'rr',v.from)+' → '+G.lengthLabel(state.items.find(i=>i.id===v.id)?.type||'rr',v.to)).join('<br>')+'</p>':''}</section><details id="outfit-details"><summary>Details zur Empfehlung</summary>${baselayerDiagnostic(r)}${!isManual?replacementHTML(r):replacementHTML(manual)}${assessmentHTML(assessment,endAssessment)}${sourceAssessmentHTML(isManual?manual:r)}<details><summary>Persönliche Bereiche und Learning</summary>${state.items.filter(G.usable).map(i=>{const l=GravelPersonal.effectiveRange(i,state,G.pointWeather(state.weather));return '<p><strong>'+esc(i.name)+'</strong><br>Deine Grundlage '+temp(i.min)+' bis '+temp(i.max)+' °C · gelernt '+temp(l.min)+' bis '+temp(l.max)+' °C · '+l.count+' passende Erfahrungen.</p>';}).join('')}</details><details><summary>Ideale Zielausrüstung</summary>${r.endTargets.map(x=>'<p><strong>'+esc(x.label)+':</strong> '+esc(x.value)+'</p>').join('')}</details>${!isManual&&r.remove.length?'<p>Später nach Bedarf ablegen: '+r.remove.map(x=>esc(x.item.name)).join(', ')+'.</p>':''}<details><summary>Spätere Kombination</summary>${outfitLines(r.endItems.map(item=>({item,group:'start'})))}</details><p class="muted">Excel ist grobe Orientierung; deine persönlichen Bereiche und Erfahrungen sind die Referenz.</p></details><section class="own-selection"><button type="button" data-mode="manual" aria-expanded="${isManual}" aria-controls="manual-outfit">Eigene Auswahl</button>${manualHTML}</section>`;}
$('#recommendation').onclick=e=>{if(e.target.closest('[data-clear-selection]')){change(s=>{s.plan.selectedIds=[];s.plan.manualInitialized=true;});return;}const b=e.target.closest('button[data-mode]');if(b){const mode=b.dataset.mode;change(s=>G.selectMode(s,mode));}};
$('#recommendation').onchange=e=>{if(e.target.matches('[data-manual-variant]')){const id=e.target.dataset.manualVariant,variant=e.target.value;change(s=>{const item=s.items.find(i=>i.id===id);if(!item?.variants.includes(variant))throw Error('Ungültige Tragevariante.');s.plan.variantSelections??={};s.plan.variantSelections[id]=variant;});return;}const box=e.target.closest('input[data-select-id]');if(box){const id=box.dataset.selectId,checked=box.checked;change(s=>G.toggleSelection(s,id,checked));}};
const wardrobeExpanded=new Set();
function renderItems(){for(const row of $('#items').querySelectorAll('.wardrobe-garment')){if(row.open)wardrobeExpanded.add(row.dataset.itemId);else wardrobeExpanded.delete(row.dataset.itemId);}const q=$('#search').value.toLowerCase(),filter=$('#filter').value,all=state.items.filter(i=>(filter==='all'||filter==='archived'&&i.archived||filter==='active'&&!i.archived||!i.archived&&i.status===filter)&&(i.name+' '+G.types[i.type]).toLowerCase().includes(q));$('#count').textContent=`${state.items.filter(i=>!i.archived&&i.status==='available').length} verfügbar · ${all.length} in dieser Ansicht`;
$('#items').innerHTML=all.length?all.map(i=>`<details class="wardrobe-garment" data-item-id="${esc(i.id)}" ${wardrobeExpanded.has(i.id)?'open':''}><summary><strong>${esc(i.name)}</strong><span class="chip">${i.archived?'Archiviert':statusNames[i.status]}</span></summary><div class="garment-details"><p class="muted">${esc(G.layerOf(i))} · ${esc(G.types[i.type])}</p><p><strong>Dein Bereich:</strong> ${temp(i.min)} bis ${temp(i.max)} °C${i.variants.length>1?' · Zip-off: Lang / Kurz':i.length!=='unspecified'?' · '+esc(G.lengthLabel(i.type,i.length)):''}</p><p>${[i.wind?'Winddicht':'',i.rain?'Wasserdicht':'',i.waterRepellent?'Wasserabweisend':''].filter(Boolean).join(' · ')||'Keine zusätzlichen Schutzeigenschaften hinterlegt.'}</p>${i.lengthReviewRequired?'<p class="warning">Bisherige Längenangabe prüfen.</p>':''}${i.notes?'<p>'+esc(i.notes)+'</p>':''}<div class="actions"><button data-action="edit" data-id="${esc(i.id)}">Bearbeiten</button><button data-properties-id="${esc(i.id)}">Alle Eigenschaften</button><button data-action="archive" data-id="${esc(i.id)}">${i.archived?'Wiederherstellen':'Archivieren'}</button></div><details><summary>Pflegehistorie (${i.care.length})</summary><p class="muted">Ein Pflegeeintrag setzt das Teil auf Verfügbar.</p><div class="actions"><button data-action="wash" data-id="${esc(i.id)}">Gewaschen</button><button data-action="proof" data-id="${esc(i.id)}">Imprägniert</button><button data-action="repair" data-id="${esc(i.id)}">Repariert</button></div><ul>${i.care.slice().reverse().map(c=>'<li>'+esc(new Date(c.at).toLocaleString('de-DE'))+' · '+esc(c.action)+'</li>').join('')}</ul></details></div></details>`).join(''):'<div class="panel"><h3>Noch nichts hier.</h3><p>Lege ein Kleidungsstück an oder ändere den Filter.</p></div>';}
function componentList(components){return components?.length?`<p><strong>Zusätzlich mitführen:</strong> ${components.map(c=>esc(c.name)).join(', ')}.</p>`:'';}
function rideComparison(r){if(r.retroactive)return '<p><strong>Tatsächlich getragen:</strong> '+r.items.map(x=>esc(x.name)+(x.selectedVariant?' ('+esc(G.lengthLabel(x.type,x.selectedVariant))+')':'')).join(', ')+'</p>';return r.recommendation?`<p><strong>Tatsächlich gewählt (${r.selectionMode==='manual'?'Eigene Auswahl':'Empfohlen'}):</strong> ${r.items.map(x=>esc(x.name)+(x.selectedVariant?' ('+esc(G.lengthLabel(x.type,x.selectedVariant))+')':'')).join(', ')||'Keine Teile'}</p>${componentList(r.packComponents)}<p><strong>Ursprüngliche automatische Empfehlung:</strong> ${r.recommendation.items.map(x=>esc(x.name)).join(', ')||'Keine verfügbaren Teile'}.</p>${componentList(r.recommendation.packComponents)}`:`<p>${r.items.map(x=>esc(x.name)+(x.selectedVariant?' ('+esc(G.lengthLabel(x.type,x.selectedVariant))+')':'')).join(', ')}</p><p class="muted">Fahrt aus früherer Version: keine getrennte Empfehlung gespeichert.</p>`;}
function zoneFeedbackForm(){return `<fieldset id="zone-feedback" hidden><legend>Welche Körperbereiche waren betroffen?</legend><p>Bereiche auswählen und einzeln bewerten. Jede Zone kann „Genau richtig“, „Zu kalt“ oder „Zu warm“ sein. Nicht ausgewählte Bereiche bleiben unbewertet.</p>${Object.entries(G.feedbackZones).map(([key,label])=>`<div class="zone-feedback-row"><label><input type="checkbox" name="zone-${key}" data-zone-toggle="${key}"> ${esc(label)}</label><label><span class="sr-only">Bewertung ${esc(label)}</span><select name="zone-feedback-${key}" aria-label="Bewertung ${esc(label)}" disabled><option value="right">Genau richtig</option><option value="cold">Zu kalt</option><option value="hot">Zu warm</option></select></label></div>`).join('')}</fieldset>`;}
function feedbackTitle(r){return r.zoneFeedback&&Object.values(r.zoneFeedback).includes('cold')&&Object.values(r.zoneFeedback).includes('hot')?'Gemischt':{cold:'Zu kalt',right:'Genau richtig',hot:'Zu warm'}[r.feedback];}
function zoneFeedbackHTML(r){return (r.feedbackPeriod?'<p><strong>Bewerteter Zeitraum:</strong> '+({start:'Am Start',end:'Am Ende',whole:'Gesamte Tour'}[r.feedbackPeriod])+'</p>':'')+(r.feedbackConditions?'<p class="muted">'+(r.feedbackConditions.source==='forecast'?'Gespeicherte Prognose für diesen Zeitraum':'Manuelle Wetterangaben')+': '+temp(r.feedbackConditions.minTemperature)+' bis '+temp(r.feedbackConditions.maxTemperature)+' °C'+(r.feedbackConditions.from?' · '+esc(weatherTime(r.feedbackConditions.from))+' → '+esc(weatherTime(r.feedbackConditions.to)):'')+'</p>':'')+(r.zoneFeedback?`<div class="zone-feedback-history"><p><strong>Bewertung je Körperzone</strong> · Nicht genannte Zonen wurden nicht bewertet.</p><ul>${Object.entries(r.zoneFeedback).map(([key,value])=>`<li>${esc(G.feedbackZones[key])}: ${{right:'Genau richtig',cold:'Zu kalt',hot:'Zu warm'}[value]}</li>`).join('')}</ul></div>`:'');}
function learningHTML(r){const zones=r.learning.zones,trend=x=>x.offset>0?'Mehr Wärmeschutz':x.offset<0?'Weniger Wärmeschutz':'Neutral';return `<details class="zone-learning"><summary>Persönliches Lernen nach Körperzonen</summary><p>${state.learning.enabled?'Aktiv':'Deaktiviert'}. Jede Zone verwendet nur ihre eigenen Bewertungen. Ältere pauschale Bewertungen gelten weiterhin für den gesamten Körper. Maximal zwölf passende Fahrten derselben Intensität und eine begrenzte Anpassung.</p><div class="table-scroll"><table><thead><tr><th>Zone</th><th>Tourstart · passende Rückmeldungen / Tendenz</th><th>Tourende · passende Rückmeldungen / Tendenz</th></tr></thead><tbody>${Object.entries(G.feedbackZones).map(([key,label])=>`<tr><th>${esc(label)}</th><td>${zones.start[key].count} / ${trend(zones.start[key])}</td><td>${zones.end[key].count} / ${trend(zones.end[key])}</td></tr>`).join('')}</tbody></table></div></details>`;}
function renderRide(){const a=state.activeRide;$('#ride').innerHTML=a?`<span class="eyebrow">UNTERWEGS</span><h3>Fahrt läuft seit ${esc(new Date(a.startedAt).toLocaleString('de-DE'))}</h3>${weatherOrigin(a.weather)}${rideComparison(a)}<form id="finish"><details><summary>Tatsächlich getragene Kleidung bestätigen</summary><p>Mitgenommen bedeutet nicht automatisch getragen. Nur bestätigte Teile fließen ins Lernen ein.</p>${a.items.map(i=>`<div class="zone-feedback-row"><label><input type="checkbox" name="worn-${esc(i.id)}" ${i.group!=='pack'?'checked':''}> ${esc(i.name)}</label><select name="usage-${esc(i.id)}" aria-label="Tragezeit ${esc(i.name)}"><option value="whole">Gesamte Tour</option><option value="start">Am Start</option><option value="end" ${i.group==='pack'?'selected':''}>Am Ende</option></select></div>`).join('')}</details><label>Wie war dein Outfit?<select name="feedback"><option value="right">Genau richtig</option><option value="cold">Zu kalt</option><option value="hot">Zu warm</option></select></label><p>„Genau richtig“ bewertet alle Körperzonen als passend. Bei „Zu kalt“ oder „Zu warm“ kannst du die betroffenen Zonen unabhängig bewerten.</p><label id="feedback-period-label" hidden>Wann war es zu warm oder zu kalt?<select name="feedbackPeriod"><option value="">Bitte auswählen</option><option value="start">Am Start</option><option value="end">Am Ende</option><option value="whole">Gesamte Tour</option></select><small>Start / Ende: erste / letzte bis zu 30 Minuten, bei kurzen Touren höchstens eine Hälfte. Learning nutzt den gespeicherten Prognoseverlauf; ohne Prognose die manuellen Temperaturen.</small></label>${zoneFeedbackForm()}<label>Rückmeldung<textarea name="note" maxlength="2000" placeholder="Was hat gut funktioniert?"></textarea></label><label><input name="laundry" type="checkbox" checked> Verwendete Teile in die Wäsche legen</label><button class="primary">Fahrt beenden</button></form>`:`<h3>Bereit für deine Tour?</h3><p>Fahrtstart speichert <strong>${state.plan.mode==='manual'?'deine eigene Auswahl':'die automatische Empfehlung'}</strong>. Die automatische Empfehlung wird zusätzlich separat als Vergleich gespeichert.</p><button id="start" class="primary" ${state.plan.mode==='recommended'&&!G.recommend(state).wearable?'disabled':''}>Fahrt starten</button>`;
$('#ride').hidden=!a;$('#tour-bar').innerHTML=a?'<span>Tour läuft</span><button type="button" id="finish-open" class="primary">Tour beenden</button>':'<span>'+ (state.plan.mode==='manual'?'Eigene Auswahl':'Empfohlenes Outfit')+'</span>';if(!a)$('#tour-bar').append($('#start'));else $('#finish-open').onclick=()=>{$('#ride').scrollIntoView?.({block:'start',behavior:'smooth'});$('#finish').elements.feedback.focus();};
renderRideHistory();}
function renderRideHistory(){$('#rides').innerHTML=state.rides.length?state.rides.slice().reverse().slice(0,20).map(r=>`<details><summary>${esc(new Date(r.startedAt).toLocaleDateString('de-DE'))} · ${Math.round((Date.parse(r.endedAt)-Date.parse(r.startedAt))/60000)} Min. · ${esc(feedbackTitle(r))}</summary><p>${r.retroactive?(r.actualWeather?'Start '+temp(r.actualWeather.series[0].temperature)+' °C → Ende '+temp(r.actualWeather.series.at(-1).temperature)+' °C':'Wetter wird nachträglich ergänzt'):Number.isFinite(r.weather.startTemp)?`Start ${temp(r.weather.startTemp)} °C → Ende ${temp(r.weather.endTemp)} °C`:`Früherer Temperaturbereich: ${temp(r.weather.min)} bis ${temp(r.weather.max)} °C`}</p>${r.retroactive?'<p class="muted">Nachträglich erfasste Tour; Wetterdaten werden separat ergänzt.</p>':weatherOrigin(r.weather)}${rideComparison(r)}${zoneFeedbackHTML(r)}<p>${esc(r.note)}</p></details>`).join(''):'<p>Deine abgeschlossenen Fahrten erscheinen hier.</p>';historyUI?.render();}
function fillLength(type,value){const field=$('#itemform').elements.namedItem('length'),allowed=G.lengthOptions(type),options=['short','long','sleeveless','zipoff'].filter(k=>k==='zipoff'?allowed.includes('short')&&allowed.includes('long'):allowed.includes(k));options.push('unspecified');field.innerHTML=options.map(k=>`<option value="${k}">${k==='zipoff'?'Zip-off':G.lengths[k]}</option>`).join('');if(value&&!options.includes(value))field.add(new Option('Bisherige Angabe – bitte prüfen',value));field.value=options.includes(value)?value:G.defaultLength(type);field.disabled=options.length===1;$('#length-hint').textContent='Kurz und Lang beziehen sich je nach Art auf Ärmel oder Hosenbeine. Zip-off bietet beide Tragevarianten in einem Kleidungsstück.';}

$('#itemform').elements.model.oninput=e=>e.target.setCustomValidity('');
function edit(id){editSession++;const i=state.items.find(x=>x.id===id)||G.item('jersey','');const f=$('#itemform');for(const k of ['id','type','status','notes','manufacturer','model'])f.elements.namedItem(k).value=k==='id'&&!id?'':i[k];for(const k of ['wind','rain','waterRepellent'])f.elements.namedItem(k).checked=i[k];f.elements.layer.value=G.layerOf(i);fillLength(i.type,i.variants.length>1?'zipoff':i.length);for(const k of ['min','max'])loadTemperature(f,k,i[k]);temperatureLabels(f,'item');const learned=GravelPersonal.effectiveRange(i,state,G.pointWeather(state.weather));$('#item-learning-range').textContent='Deine Grundlage: '+temp(i.min)+' bis '+temp(i.max)+' °C · Gelernte Empfehlung für ähnliche Bedingungen: '+temp(learned.min)+' bis '+temp(learned.max)+' °C · '+learned.count+' passende Erfahrungen. Änderungen behalten alle Erfahrungen; sie werden mit der neuen Grundlage neu bewertet.';$('#editor-title').textContent=id?'Kleidungsstück bearbeiten':'Neues Kleidungsstück';$('#editor').showModal();}
$('#itemform').elements.layer.innerHTML=G.layerNames.map(x=>`<option>${x}</option>`).join('');
$('#itemform').elements.layer.onchange=e=>{const f=$('#itemform'),choices=Object.keys(G.types).filter(t=>G.layerOf(t)===e.target.value);if(!choices.includes(f.elements.type.value)){f.elements.type.value=choices[0];f.elements.type.dispatchEvent(new Event('change'));}};
$('#itemform').elements.type.innerHTML=G.typeOrder.map(k=>[k,G.types[k]]).map(([k,v])=>`<option value="${k}">${v}</option>`).join('');
$('#itemform').elements.type.onchange=e=>{const f=$('#itemform'),i=G.item(e.target.value);f.elements.layer.value=G.layerOf(i);const oldLength=f.elements.namedItem('length').value;fillLength(i.type,(G.lengthOptions(i.type).includes(oldLength)||oldLength==='zipoff'&&G.lengthOptions(i.type).includes('long')&&G.lengthOptions(i.type).includes('short'))?oldLength:G.defaultLength(i.type));if(!f.elements.id.value){f.elements.layer.value=G.layerOf(i);fillLength(i.type,i.variants.length>1?'zipoff':i.length);for(const k of ['min','max'])loadTemperature(f,k,i[k]);for(const k of ['wind','rain','waterRepellent'])f.elements.namedItem(k).checked=i[k];temperatureLabels(f,'item');}};
$('#itemform').onsubmit=async e=>{e.preventDefault();const f=e.target;if(+f.elements.min.value>+f.elements.max.value){f.elements.max.setCustomValidity('Die obere Temperatur muss mindestens der unteren entsprechen.');f.elements.max.reportValidity();return;}const session=editSession,data={};for(const k of ['id','type','status','notes','length','manufacturer','model'])data[k]=f.elements.namedItem(k).value.trim();if(!data.model){f.elements.model.setCustomValidity('Bitte ein Modell oder eine Bezeichnung eintragen.');f.elements.model.reportValidity();return;}data.name=data.model;for(const k of ['min','max'])data[k]=savedTemperature(f,k);for(const k of ['wind','rain','waterRepellent'])data[k]=f.elements.namedItem(k).checked;data.layer=G.layerOf(data.type);data.variants=data.length==='zipoff'?['long','short']:[];if(data.length==='zipoff')data.length='long';const ok=await change(s=>{let i=s.items.find(x=>x.id===data.id);if(data.id&&!i)throw Error('Das Kleidungsstück ist nicht mehr vorhanden.');if(!i){i=G.item(data.type);s.items.push(i);}const {id,...fields}=data;if(!G.lengthOptions(data.type).includes(data.length)&&!(i.lengthReviewRequired&&i.type===data.type&&i.length===data.length))throw Error('Bitte eine passende Länge wählen.');if(fields.min!==i.min||fields.max!==i.max)i.rangeChangedAt=new Date().toISOString();Object.assign(i,fields);if(G.lengthOptions(i.type).includes(i.length))delete i.lengthReviewRequired;});if(ok&&session===editSession)$('#editor').close();};
for(const k of ['min','max'])$('#itemform').elements.namedItem(k).oninput=()=>$('#itemform').elements.max.setCustomValidity('');$('#new').onclick=()=>edit();$('#close').onclick=()=>$('#editor').close();
$('#items').onclick=e=>{const b=e.target.closest('button[data-action]');if(!b)return;if(b.dataset.action==='edit')return edit(b.dataset.id);change(s=>{const i=s.items.find(x=>x.id===b.dataset.id);if(!i)throw Error('Kleidungsstück nicht mehr vorhanden.');if(b.dataset.action==='archive')i.archived=!i.archived;else {i.care.push({at:new Date().toISOString(),action:{wash:'Gewaschen',proof:'Imprägniert',repair:'Repariert'}[b.dataset.action]});i.status='available';}});};
$('#search').oninput=renderItems;$('#filter').onchange=renderItems;
$('#weather').onsubmit=e=>{e.preventDefault();cancelWeather();const d=forecastDraft();let t;try{t=P.windowFor(d,state.route);}catch(error){say(error.message);return;}const f=e.target,w={};for(const k of Object.keys(G.weather))w[k]=['startTemp','endTemp'].includes(k)?savedTemperature(f,k):k==='duration'?((t.ridingMinutes||t.minutes)<60?0:(t.ridingMinutes||t.minutes)<=120?1:2):+f.elements[k].value;const optional=Object.fromEntries(Object.keys(G.optionalDefaults()).map(k=>[k,f.elements['opt-'+k].value]));change(s=>{const altered=['startTemp','endTemp','wind','rain'].some(k=>w[k]!==s.weather[k]);if(d.weatherSource==='manual'||manualWeatherMode||altered||!P.matches(s.weather.forecast,d,s.route))delete s.weather.forecast;s.tripPlan=d;s.weather={...s.weather,...w,rideMinutes:t.ridingMinutes||t.minutes,planning:{mode:d.mode,startAt:s.weather.forecast?.startAt||t.startAt}};s.optional=optional;}).then(ok=>{if(ok){manualWeatherMode=false;showPlanning(false);}});};
$('#tour-bar').onclick=$('#ride').onclick=e=>{if(e.target.id==='start'){if(state.tripPlan?.weatherSource&&state.tripPlan.weatherSource!=='manual'&&!state.weather.forecast)return say('Bitte die gewählte Wetterquelle laden oder manuelle Wetterwerte übernehmen.');if(state.weather.forecast&&!forecastMatches(state.weather.forecast,forecastDraft()))return say('Die Zeitplanung wurde geändert. Lade neue Wetterdaten oder übernimm manuelle Werte.');change(s=>G.startRide(s));}};
$('#ride').onchange=e=>{const f=e.target.form;if(!f||f.id!=='finish')return;if(e.target.name==='feedback'){$('#zone-feedback').hidden=e.target.value==='right';$('#feedback-period-label').hidden=e.target.value==='right';f.elements.feedbackPeriod.required=e.target.value!=='right';return;}if(e.target.matches('[data-zone-toggle]')){const field=f.elements.namedItem('zone-feedback-'+e.target.dataset.zoneToggle);field.disabled=!e.target.checked;if(e.target.checked&&!field.dataset.edited)field.value=f.elements.feedback.value==='hot'?'hot':'cold';}else if(e.target.name.startsWith('zone-feedback-'))e.target.dataset.edited='true';};
$('#ride').onsubmit=e=>{e.preventDefault();const f=e.target,zoneFeedback={};for(const key of Object.keys(G.feedbackZones))if(f.elements.namedItem('zone-'+key).checked)zoneFeedback[key]=f.elements.namedItem('zone-feedback-'+key).value;const itemUsage=state.activeRide.items.filter(i=>f.elements.namedItem('worn-'+i.id).checked).map(i=>({id:i.id,period:f.elements.namedItem('usage-'+i.id).value}));const data={itemUsage,feedback:f.elements.feedback.value,feedbackPeriod:f.elements.feedback.value==='right'?'whole':f.elements.feedbackPeriod.value,zoneFeedback,note:f.elements.note.value.trim(),laundry:f.elements.laundry.checked};change(s=>G.finishRide(s,data)).then(ok=>{if(ok){historyUI.run();historyUI.completeLocationIfNeeded(state.rides.at(-1).id);}});};
for(const b of document.querySelectorAll('nav button'))b.onclick=()=>{for(const x of document.querySelectorAll('nav button')){x.removeAttribute('aria-current');$('#'+x.dataset.tab).hidden=x!==b;}b.setAttribute('aria-current','page');$('#tour-bar').hidden=b.dataset.tab!=='outfit'||planningOpen;};
$('#export').onclick=async()=>{try{const data=await read(),blob=new Blob([JSON.stringify({...data,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Gravel-Outfit-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);say('Sicherungsdatei wurde zum Download bereitgestellt.');}catch(e){say('Export fehlgeschlagen: '+e.message);}};
$('#import').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>10*1024*1024)throw Error('Datei ist größer als 10 MB.');let d=JSON.parse(await file.text());if(d.version===2&&Array.isArray(d.clothes))d=G.migrate(d.clothes,d.props,d.settings);d=G.upgrade(d);if(confirm('Alle aktuellen Daten einschließlich Fahrten durch diese Sicherung ersetzen?'))await change(s=>{for(const k of Object.keys(s))delete s[k];Object.assign(s,d);});}catch(err){say('Import fehlgeschlagen: '+err.message);}e.target.value='';};
$('#persist').onclick=async()=>{try{$('#storage').textContent=await navigator.storage?.persist?.()?'Dauerhafte Speicherung wurde gewährt.':'Der Browser hat dauerhafte Speicherung nicht gewährt. Bitte weiterhin Sicherungen exportieren.';}catch(e){$('#storage').textContent=e.message;}};
let installPrompt;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('#install').hidden=false;});$('#install').onclick=async()=>{await installPrompt.prompt();$('#install').hidden=true;};
async function connectivity(){const label=$('#connection');if(!navigator.onLine){label.textContent='Offline · lokal nutzbar';return;}label.textContent='Verbindung wird geprüft …';try{await fetch('./version.json?check='+Date.now(),{cache:'no-store',signal:AbortSignal.timeout(6000)}).then(r=>{if(!r.ok)throw Error();});label.textContent='Online';}catch{label.textContent='Server nicht erreichbar · lokal nutzbar';}}
window.addEventListener('online',connectivity);window.addEventListener('offline',connectivity);document.addEventListener('visibilitychange',()=>{if(!document.hidden){connectivity();if(db)read().then(s=>{if(s&&!busy&&!forecastLoading){state=G.upgrade(s);render();}});}});
(async()=>{connectivity();try{await openDB();state=await read();if(!state){state=G.seed();G.importExcelItems(state);try{const old=JSON.parse(localStorage.getItem('gravel-v4-clothes'));if(old){state=G.migrate(old,JSON.parse(localStorage.getItem('gravel-v5-properties'))||{},JSON.parse(localStorage.getItem('gravel-v4-settings'))||{});say('Dein bisheriger Kleiderschrank wurde übernommen.');}}catch{say('Alte Daten konnten nicht automatisch übernommen werden. Sie bleiben im Browser erhalten. Importiere bei Bedarf eine bisherige JSON-Sicherung.');}await write(state);}const upgraded=G.upgrade(state);if(state.schemaVersion!==upgraded.schemaVersion)await write(upgraded);state=upgraded;if(preparePersonalState(state)){G.validate(state);await write(state);}historyUI=GravelHistoryUI.init({getState:()=>state,readState:read,change,say,onWeatherUpdate:()=>{renderRecommendation();renderRideHistory();renderTourSummary();}});render();historyUI.run();}catch(e){say('Lokaler Speicher nicht verfügbar: '+e.message+'. Bitte Browser-Speicherung erlauben und neu laden.');document.querySelectorAll('main button,main input,main select').forEach(x=>x.disabled=true);}
if('serviceWorker' in navigator){try{const reg=await navigator.serviceWorker.register('./sw.js');await navigator.serviceWorker.ready;$('#offline').textContent='Offline-Version ist vorbereitet. Beim ersten Aufruf bitte warten, bis die Seite vollständig geladen ist.';reg.addEventListener('updatefound',()=>{const worker=reg.installing;worker.addEventListener('statechange',()=>{if(worker.state==='installed'&&navigator.serviceWorker.controller)say('Eine neue Version ist vorbereitet. Schließe alle App-Tabs und öffne die App erneut.');});});}catch{$('#offline').textContent='Offline-Speicher konnte nicht eingerichtet werden. Bitte über HTTPS oder localhost öffnen.';}}else $('#offline').textContent='Dieser Browser unterstützt keinen Service Worker.';
})();

$('#excel-import').onclick=async()=>{let added=0;await change(s=>{added=G.importExcelItems(s);});$('#excel-import-status').textContent=added+' fehlende Excel-Einträge ergänzt. Bestehende Einträge unverändert.';};
$('#learning-enabled').onchange=e=>{const enabled=e.target.checked;change(s=>{s.learning.enabled=enabled;});};
$('#intensity-source').innerHTML='<table><thead><tr><th>Temperatur</th><th>Niedrig</th><th>Mittel</th><th>Hoch</th></tr></thead><tbody>'+G.X.intensityOriginal.map(r=>`<tr><th>${r.temperature} °C</th><td>${esc(r.low)}</td><td>${esc(r.normal)}</td><td>${esc(r.high)}</td></tr>`).join('')+'</tbody></table>';

$('#appearance').onchange=e=>{const appearance=e.target.value;change(s=>{s.appearance=appearance;});};
